INSERT INTO recipes (id,title,ingredients,steps,image,source_url,prep_time,cook_time,servings,credit_kind,credit_name,tags,language,step_ingredients) VALUES ('tablewise:catalog:chef-prati:cooked-adjika','Cooked adjika',ARRAY['1 kg ripe tomatoes','3 red bell peppers','10–15 hot peppers, seeds included','½ cup crushed garlic','½ cup olive or sunflower oil','3 tbsp vinegar','2 tbsp sugar','2 tsp salt','2–3 tbsp concentrated tomato paste, optional','5 carrots, finely grated','3 tbsp onion jam or caramelized onion']::text[],ARRAY['Fry the carrots in the oil until golden. Transfer to a plate, leaving the oil in the pan.','Blend the tomatoes, both kinds of pepper and some of the garlic. Drain off excess liquid.','Add the purée to the reserved oil. Cook over medium-low heat until it begins to thicken.','Stir in the remaining garlic and cook for about 5 minutes.','Add the vinegar, sugar, salt and optional tomato paste. Cook, stirring, until spreadable.','Return the fried carrots to the pan. Add the onion jam or caramelized onion and cook for 5 more minutes. Taste and adjust the seasoning.']::text[],NULL,'https://chef-prati.com/%d7%90%d7%92%d7%99%d7%a7%d7%94-%d7%9e%d7%91%d7%95%d7%a9%d7%9c%d7%aa-%d7%94%d7%9e%d7%98%d7%91%d7%95%d7%97%d7%94-%d7%a9%d7%9c-%d7%94%d7%a7%d7%95%d7%95%d7%a7%d7%96%d7%99%d7%9d-%d7%9e%d7%aa%d7%9b%d7%95/',20,45,'12','chef','Mark Aldarov',ARRAY['Eastern European','Vegetarian','Vegan','Dairy-free']::text[],'en','[["½ cup olive or sunflower oil", "5 carrots, finely grated"], ["1 kg ripe tomatoes", "3 red bell peppers", "10–15 hot peppers, seeds included", "½ cup crushed garlic"], [], ["½ cup crushed garlic"], ["3 tbsp vinegar", "2 tbsp sugar", "2 tsp salt", "2–3 tbsp concentrated tomato paste, optional"], ["3 tbsp onion jam or caramelized onion"]]'::jsonb) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,source_url=EXCLUDED.source_url,prep_time=EXCLUDED.prep_time,cook_time=EXCLUDED.cook_time,servings=EXCLUDED.servings,credit_kind=EXCLUDED.credit_kind,credit_name=EXCLUDED.credit_name,tags=EXCLUDED.tags,language=EXCLUDED.language,ingredient_parts=NULL,step_ingredients=EXCLUDED.step_ingredients,step_analysis=NULL,updated_at=now();
INSERT INTO recipe_sources (recipe_id,owner_id,provider,original_url,canonical_url,external_video_id,status) VALUES ('tablewise:catalog:chef-prati:cooked-adjika','catalog','youtube','https://www.youtube.com/watch?v=gCgHZWk1LR8','https://www.youtube.com/watch?v=gCgHZWk1LR8','gCgHZWk1LR8','ready') ON CONFLICT (recipe_id) DO UPDATE SET original_url=EXCLUDED.original_url,canonical_url=EXCLUDED.canonical_url,external_video_id=EXCLUDED.external_video_id,status=EXCLUDED.status,updated_at=now();
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:chef-prati:cooked-adjika','he','אג׳יקה מבושלת',ARRAY['1 ק״ג עגבניות בשלות','3 פלפלים אדומים מתוקים','10–15 פלפלים חריפים עם הגרעינים','חצי כוס שום כתוש','חצי כוס שמן זית או חמניות','3 כפות חומץ','2 כפות סוכר','2 כפיות מלח','2–3 כפות רסק עגבניות מרוכז, לפי הטעם','5 גזרים מגוררים דק','3 כפות ריבת בצל או בצל מקורמל']::text[],ARRAY['מטגנים את הגזר בשמן עד להזהבה. מעבירים לצלחת ומשאירים את השמן בסיר.','טוחנים את העגבניות, שני סוגי הפלפלים וחלק מהשום. מסננים עודפי נוזלים.','מוסיפים את המחית לשמן שבסיר ומבשלים על אש בינונית־נמוכה עד להסמכה.','מוסיפים את יתרת השום ומבשלים כ־5 דקות.','מוסיפים חומץ, סוכר, מלח ורסק אם משתמשים. מערבבים ומבשלים עד שמתקבל ממרח.','מחזירים את הגזר המטוגן, מוסיפים ריבת בצל או בצל מקורמל ומבשלים עוד 5 דקות. טועמים ומתקנים תיבול.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:chef-prati:cooked-adjika','ru','Варёная аджика',ARRAY['1 кг спелых помидоров','3 красных сладких перца','10–15 острых перцев с семенами','½ стакана измельчённого чеснока','½ стакана оливкового или подсолнечного масла','3 ст. л. уксуса','2 ст. л. сахара','2 ч. л. соли','2–3 ст. л. концентрированной томатной пасты, по желанию','5 морковок, натёртых на мелкой тёрке','3 ст. л. лукового конфитюра или карамелизированного лука']::text[],ARRAY['Обжарьте морковь в масле до золотистого цвета. Переложите на тарелку, оставив масло в посуде.','Измельчите помидоры, оба вида перца и часть чеснока. Слейте лишнюю жидкость.','Добавьте пюре в оставшееся масло. Готовьте на умеренно слабом огне, пока оно не начнёт густеть.','Добавьте оставшийся чеснок и готовьте около 5 минут.','Добавьте уксус, сахар, соль и по желанию томатную пасту. Готовьте, помешивая, до консистенции густой пасты.','Верните обжаренную морковь, добавьте луковый конфитюр или карамелизированный лук и готовьте ещё 5 минут. Попробуйте и приправьте по вкусу.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipes (id,title,ingredients,steps,image,source_url,prep_time,cook_time,servings,credit_kind,credit_name,tags,language,step_ingredients) VALUES ('tablewise:catalog:chef-prati:herb-aioli','Herb aioli',ARRAY['500 g mayonnaise','3–4 garlic cloves','2 tsp date syrup','2 tbsp olive oil','20 mint leaves','1 bunch basil','A generous handful of scallion greens','⅓ bunch parsley','⅓ bunch dill','Pinch of salt','Pinch of black or white pepper','1 tbsp lemon juice']::text[],ARRAY['Put the mayonnaise, garlic, date syrup, oil, salt, pepper and lemon juice in a blender.','Add the mint, basil, scallion greens, parsley and dill. Blend until smooth and uniformly green.','Taste and adjust the seasoning, acidity and sweetness as needed.']::text[],NULL,'https://chef-prati.com/%d7%90%d7%99%d7%95%d7%9c%d7%99-%d7%a2%d7%a9%d7%91%d7%99-%d7%aa%d7%99%d7%91%d7%95%d7%9c-%d7%9e%d7%aa%d7%9b%d7%95%d7%9f-%d7%a7%d7%9c-%d7%a2%d7%9d-%d7%a1%d7%a8%d7%98%d7%95%d7%9f/',10,0,'8','chef','Mark Aldarov',ARRAY['Mediterranean','Vegetarian']::text[],'en','[["500 g mayonnaise", "3–4 garlic cloves", "2 tsp date syrup", "2 tbsp olive oil", "Pinch of salt", "Pinch of black or white pepper", "1 tbsp lemon juice"], ["20 mint leaves", "1 bunch basil", "A generous handful of scallion greens", "⅓ bunch parsley", "⅓ bunch dill"], []]'::jsonb) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,source_url=EXCLUDED.source_url,prep_time=EXCLUDED.prep_time,cook_time=EXCLUDED.cook_time,servings=EXCLUDED.servings,credit_kind=EXCLUDED.credit_kind,credit_name=EXCLUDED.credit_name,tags=EXCLUDED.tags,language=EXCLUDED.language,ingredient_parts=NULL,step_ingredients=EXCLUDED.step_ingredients,step_analysis=NULL,updated_at=now();
INSERT INTO recipe_sources (recipe_id,owner_id,provider,original_url,canonical_url,external_video_id,status) VALUES ('tablewise:catalog:chef-prati:herb-aioli','catalog','youtube','https://www.youtube.com/watch?v=iPvw9DdEMRw','https://www.youtube.com/watch?v=iPvw9DdEMRw','iPvw9DdEMRw','ready') ON CONFLICT (recipe_id) DO UPDATE SET original_url=EXCLUDED.original_url,canonical_url=EXCLUDED.canonical_url,external_video_id=EXCLUDED.external_video_id,status=EXCLUDED.status,updated_at=now();
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:chef-prati:herb-aioli','he','איולי עשבי תיבול',ARRAY['500 גרם מיונז','3–4 שיני שום','2 כפיות סילאן','2 כפות שמן זית','20 עלי נענע','צרור בזיליקום','בצל ירוק בנדיבות, החלק הירוק בלבד','שליש צרור פטרוזיליה','שליש צרור שמיר','קורט מלח','קורט פלפל שחור או לבן','כף מיץ לימון']::text[],ARRAY['שמים בבלנדר את המיונז, השום, הסילאן, השמן, המלח, הפלפל ומיץ הלימון.','מוסיפים נענע, בזיליקום, בצל ירוק, פטרוזיליה ושמיר. טוחנים עד שמתקבל רוטב ירוק וחלק.','טועמים ומאזנים את התיבול, החמיצות והמתיקות לפי הטעם.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:chef-prati:herb-aioli','ru','Айоли с зеленью',ARRAY['500 г майонеза','3–4 зубчика чеснока','2 ч. л. финикового сиропа','2 ст. л. оливкового масла','20 листочков мяты','1 пучок базилика','Зелёные перья лука, щедрая горсть','⅓ пучка петрушки','⅓ пучка укропа','Щепотка соли','Щепотка чёрного или белого перца','1 ст. л. лимонного сока']::text[],ARRAY['Положите в блендер майонез, чеснок, финиковый сироп, масло, соль и перец. Влейте лимонный сок.','Добавьте мяту, базилик, зелёный лук, петрушку и укроп. Измельчите до получения однородного зелёного соуса.','Попробуйте и при необходимости отрегулируйте вкус, кислоту и сладость.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipes (id,title,ingredients,steps,image,source_url,prep_time,cook_time,servings,credit_kind,credit_name,tags,language,step_ingredients) VALUES ('tablewise:catalog:chef-prati:garlic-aioli','Garlic aioli',ARRAY['500 g homemade or store-bought mayonnaise','3 garlic cloves','1 tbsp date syrup','1 tbsp olive oil']::text[],ARRAY['Put the mayonnaise, garlic, date syrup and olive oil in a bowl.','Blend with an immersion blender until combined. Taste and adjust the seasoning.']::text[],NULL,'https://chef-prati.com/%d7%90%d7%99%d7%95%d7%9c%d7%99-%d7%a9%d7%95%d7%9d-%d7%9e%d7%aa%d7%9b%d7%95%d7%9f-%d7%a4%d7%a9%d7%95%d7%98-%d7%a9%d7%9c-%d7%a9%d7%a3-%d7%a4%d7%a8%d7%98%d7%99/',5,0,'8','chef','Mark Aldarov',ARRAY['Mediterranean','Vegetarian']::text[],'en','[["500 g homemade or store-bought mayonnaise", "3 garlic cloves", "1 tbsp date syrup", "1 tbsp olive oil"], []]'::jsonb) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,source_url=EXCLUDED.source_url,prep_time=EXCLUDED.prep_time,cook_time=EXCLUDED.cook_time,servings=EXCLUDED.servings,credit_kind=EXCLUDED.credit_kind,credit_name=EXCLUDED.credit_name,tags=EXCLUDED.tags,language=EXCLUDED.language,ingredient_parts=NULL,step_ingredients=EXCLUDED.step_ingredients,step_analysis=NULL,updated_at=now();
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:chef-prati:garlic-aioli','he','איולי שום',ARRAY['500 גרם מיונז ביתי או קנוי','3 שיני שום','כף סילאן','כף שמן זית']::text[],ARRAY['שמים בקערה את המיונז, השום, הסילאן ושמן הזית.','טוחנים בבלנדר מוט עד לאיחוד. טועמים ומתקנים תיבול.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
INSERT INTO recipe_translations (recipe_id,language,title,ingredients,steps,translated_by) VALUES ('tablewise:catalog:chef-prati:garlic-aioli','ru','Чесночный айоли',ARRAY['500 г домашнего или покупного майонеза','3 зубчика чеснока','1 ст. л. финикового сиропа','1 ст. л. оливкового масла']::text[],ARRAY['Положите в миску майонез, чеснок и финиковый сироп, влейте оливковое масло.','Взбейте погружным блендером до однородности. Попробуйте и при необходимости приправьте.']::text[],'ai') ON CONFLICT (recipe_id,language) DO UPDATE SET title=EXCLUDED.title,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,translated_by=EXCLUDED.translated_by;
